CREATE TABLE parcel_class_area AS
SELECT cod_imovel, mbmode24, sum(field_area_ha) AS area_ha
FROM matched_full
WHERE cod_imovel IN (SELECT cod_imovel FROM flagged)
GROUP BY 1,2;

CREATE TABLE parcel_class_ranked AS
SELECT cod_imovel, mbmode24, area_ha,
       row_number() OVER (PARTITION BY cod_imovel ORDER BY area_ha DESC, mbmode24 ASC) AS rn
FROM parcel_class_area;

CREATE TABLE dominant_class AS
SELECT cod_imovel, mbmode24 AS dominant_mb, area_ha
FROM parcel_class_ranked WHERE rn = 1;

SELECT * FROM dominant_class ORDER BY cod_imovel;

